=== templates/chapter/template.js
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var K = 0.53;
  var name = String(v.name || "").toUpperCase();
  var chap = String(v.chapter || "").toUpperCase();

  var fit = MC.fit(name, d.vertical
    ? { maxWidth: W * 0.86, maxSize: 76, minSize: 26, k: K, maxLines: 3, maxHeight: H * 0.3 }
    : { maxWidth: W * 0.84, maxSize: 92, minSize: 26, k: K, maxLines: 2, maxHeight: H * 0.36 });
  var nEl = document.getElementById("ch-name");
  nEl.style.fontSize = fit.size + "px";
  var parts = MC.renderLines(nEl, fit.lines, { chars: true });
  var nameH = fit.lines.length * fit.size;

  var tagSize = d.vertical ? 30 : 30;
  var bandH = nameH + fit.size * 0.5 + 64;
  var cy = H * (d.vertical ? 0.45 : 0.5);
  var bandTop = cy - bandH / 2;
  var band = document.getElementById("ch-band"), stripe = document.getElementById("ch-stripe");
  band.style.top = bandTop + "px"; band.style.height = bandH + "px";
  stripe.style.top = (bandTop + 14) + "px"; stripe.style.height = bandH + "px";
  nEl.style.top = (bandTop + 52 + fit.size * 0.1) + "px";

  // stepped pixel edges on both ends of each band (they travel with the band)
  var STEP = 22;
  [band, stripe].forEach(function (el) {
    var full = bandH + 8;
    for (var side = 0; side < 2; side++) {
      for (var i = 0; i < 3; i++) {
        var s = document.createElement("div");
        s.className = "ch-step";
        var h = Math.round(full * (1 - i / 3.2));
        s.style.width = (STEP + 4) + "px";
        s.style.height = h + "px";
        s.style.top = (-4 + (full - h) / 2) + "px";
        s.style.left = (side === 0 ? (W - 4 + i * STEP) : (-STEP - i * STEP)) + "px";
        s.style.borderLeftWidth = side === 0 ? "0" : "4px";
        s.style.borderRightWidth = side === 0 ? "4px" : "0";
        el.appendChild(s);
      }
    }
  });

  var tag = document.getElementById("ch-tag");
  tag.textContent = chap;
  tag.style.fontSize = Math.floor(Math.min(tagSize, (W * 0.6) / (Math.max(chap.length, 1) * K))) + "px";
  tag.style.top = (bandTop - 20) + "px";
  tag.style.left = (d.vertical ? W * 0.07 : W * 0.08) + "px";
  if (!chap) tag.style.display = "none";

  var EDGE = STEP * 3 + 8;
  var tl = gsap.timeline({ paused: true });
  // wipe in (from left)
  tl.fromTo(stripe, { x: -(W + EDGE) }, { x: 0, duration: 0.34, ease: "power4.out" }, 0);
  tl.fromTo(band, { x: -(W + EDGE) }, { x: 0, duration: 0.34, ease: "power4.out" }, 0.05);
  tl.fromTo(tag, { scale: 0, rotation: -20 }, { scale: 1, rotation: -4, duration: 0.28, ease: "back.out(2.8)" }, 0.24);
  tl.fromTo(parts.chars, { y: 46, scale: 0.2, opacity: 0 },
    { y: 0, scale: 1, opacity: 1, duration: 0.26, ease: "back.out(2.6)", stagger: { each: Math.min(0.03, 0.5 / Math.max(parts.chars.length, 1)) } }, 0.26);
  // a little accent kick on the tag mid-hold
  tl.to(tag, { keyframes: [{ rotation: 3, scale: 1.08 }, { rotation: -4, scale: 1 }], duration: 0.22, ease: "power1.inOut" }, 1.0);
  // wipe out (to the right)
  var out = d.duration - 0.42;
  tl.to(parts.chars, { y: -36, opacity: 0, duration: 0.16, ease: "power2.in", stagger: { each: 0.008 } }, out);
  tl.to(tag, { scale: 0, rotation: 15, duration: 0.16, ease: "back.in(2)" }, out);
  tl.to(band, { x: W + EDGE, duration: 0.3, ease: "power3.in" }, out + 0.1);
  tl.to(stripe, { x: W + EDGE, duration: 0.3, ease: "power3.in" }, out + 0.14);
  return tl;
});
