MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var style = String(v.style || "color").trim().toLowerCase();
  var color = String(v.color || "#5FBF3A");

  /* ---- 16x16 procedural block textures (seeded) -> SVG data URIs ---- */
  function palette(st) {
    switch (st) {
      case "stone":      return ["#7f7f7f", "#747474", "#8c8c8c", "#686868", "#9a9a9a"];
      case "dirt":       return ["#866043", "#79553a", "#966c4a", "#5f4430", "#b9855c"];
      case "deepslate":  return ["#4d4d55", "#44444b", "#5a5a62", "#36363c", "#66666e"];
      case "obsidian":   return ["#140f1f", "#1c1530", "#0d0a15", "#2a1f45", "#3b2d63"];
      case "netherrack": return ["#6f3535", "#7f3d3d", "#622b2b", "#4f2020", "#9c5050"];
      case "sand":       return ["#dbd3a0", "#d1c890", "#e6dfb0", "#c4b97c", "#efe8c4"];
      default:
        return [color, MC.shade(color, -0.08), MC.shade(color, 0.08), MC.shade(color, -0.18), MC.shade(color, 0.18)];
    }
  }
  function texture(st, seed) {
    var rnd = MC.rng(seed), pal = palette(st), rows = [], grassPal = palette("color");
    if (st === "grass") { pal = palette("dirt"); grassPal = ["#5FBF3A", "#56ad34", "#6fd145", "#4a9a2c", "#7fdc55"]; }
    var drip = [];
    for (var x = 0; x < 16; x++) drip.push(3 + Math.floor(rnd() * 3));
    var map = { a: 0, b: 1, c: 2, d: 3, e: 4 }, keys = "abcde", gkeys = "fghij", s = [];
    for (var y = 0; y < 16; y++) {
      var row = "";
      for (var x2 = 0; x2 < 16; x2++) {
        var r = rnd(), k = r < 0.42 ? 0 : r < 0.62 ? 1 : r < 0.8 ? 2 : r < 0.93 ? 3 : 4;
        row += (st === "grass" && y < drip[x2]) ? gkeys.charAt(k) : keys.charAt(k);
      }
      s.push(row);
    }
    var pm = { a: pal[0], b: pal[1], c: pal[2], d: pal[3], e: pal[4],
               f: grassPal[0], g: grassPal[1], h: grassPal[2], i: grassPal[3], j: grassPal[4] };
    var svg = MC.pixelSVG(s, pm, 1).replace(/ width="16" height="16"/, "");
    return 'url("data:image/svg+xml;utf8,' + encodeURIComponent(svg) + '")';
  }
  var texs = [];
  for (var t = 0; t < 4; t++) texs.push(texture(style, 1337 + t * 101));

  /* ---- grid: 64px logical blocks (128px in the full render), +1px overlap so no seams ---- */
  var B = 64;
  var cols = Math.ceil(W / B), rows = Math.ceil(H / B);
  var ox = Math.floor((W - cols * B) / 2), oy = Math.floor((H - rows * B) / 2);
  var grid = document.getElementById("pw-grid"), cells = [], inT = [], outT = [];
  var rnd = MC.rng(4242), maxD = cols + rows - 2;
  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      var e = document.createElement("div");
      e.className = "pw-b";
      e.style.left = (ox + c * B - 1) + "px"; e.style.top = (oy + r * B - 1) + "px";
      e.style.width = (B + 2) + "px"; e.style.height = (B + 2) + "px";
      e.style.backgroundImage = texs[Math.floor(rnd() * texs.length)];
      grid.appendChild(e); cells.push(e);
      inT.push(((c + r) / maxD) * 0.55 + rnd() * 0.45);   // noisy diagonal wave
      outT.push(((c + r) / maxD) * 0.4 + rnd() * 0.6);
    }
  }

  var IN_SPREAD = 0.25, IN_DUR = 0.12;   // last block lands at 0.37s
  var OUT_AT = 0.48, OUT_SPREAD = 0.28, OUT_DUR = 0.14; // clear by 0.90s
  var tl = gsap.timeline({ paused: true });
  cells.forEach(function (el, i) {
    tl.fromTo(el, { scale: 0 }, { scale: 1, duration: IN_DUR, ease: "back.out(2.2)" }, inT[i] * IN_SPREAD);
    tl.to(el, { scale: 0, duration: OUT_DUR, ease: "back.in(2.2)" }, OUT_AT + outT[i] * OUT_SPREAD);
  });
  return tl;
});
EOF
cd ../..; ls

