      case "dirt":       return ["#866043", "#79553a", "#966c4a", "#5f4430", "#b9855c"];
      case "deepslate":  return ["#4d4d55", "#44444b", "#5a5a62", "#36363c", "#66666e"];
      case "obsidian":   return ["#140f1f", "#1c1530", "#0d0a15", "#2a1f45", "#3b2d63"];
      case "netherrack": return ["#6f3535", "#7f3d3d", "#622b2b", "#4f2020", "#9c5050"];
      case "sand":       return ["#dbd3a0", "#d1c890", "#e6dfb0", "#c4b97c", "#efe8c4"];
      default:
        return [color, MC.shade(color, -0.08), MC.shade(color, 0.08), MC.shade(color, -0.18), MC.shade(color, 0.18)];
    }
  }
  function canvasURL(draw) {
    var cv = document.createElement("canvas"); cv.width = 16; cv.height = 16;
    draw(cv.getContext("2d"));
