    var pal = palette(st === "grass" ? "dirt" : st).map(function (c) { return MC.shade(c, tint); });
    var gp = ["#5FBF3A", "#56ad34", "#6fd145", "#4a9a2c", "#7fdc55"];
    var drip = [];
    for (var x = 0; x < 16; x++) drip.push(3 + Math.floor(rnd() * 3));
    return canvasURL(function (cx) {
      for (var y = 0; y < 16; y++) for (var x2 = 0; x2 < 16; x2++) {
        var r = rnd(), k = r < 0.42 ? 0 : r < 0.62 ? 1 : r < 0.8 ? 2 : r < 0.93 ? 3 : 4;
        cx.fillStyle = (st === "grass" && y < drip[x2]) ? gp[k] : pal[k];
