    var br = [];
    var sx = 6 + Math.floor(rnd() * 4), sy = 6 + Math.floor(rnd() * 4);
    for (var b = 0; b < 6; b++) br.push({ x: sx, y: sy, d: Math.floor(b * 8 / 6 + rnd() * 1.5) % 8, alive: true });
    function add(x, y) {
      var k = x + "," + y;
      if (!seen[k] && x >= 0 && y >= 0 && x < 16 && y < 16) { seen[k] = 1; px.push([x, y]); }
