      var x0 = ox + c * B, y0 = oy + r * B;
      var dist = Math.min(1, Math.hypot(x0 + B / 2 - W / 2, y0 + B / 2 - H / 2) / maxDist); // 0 centre .. 1 corner
      var tex = texs[Math.floor(rnd() * texs.length)], ck = cracks[Math.floor(rnd() * cracks.length)];
      var e = document.createElement("div");
      e.className = "bb-b";
      e.style.left = (x0 - 1) + "px"; e.style.top = (y0 - 1) + "px";
      e.style.width = (B + 2) + "px"; e.style.height = (B + 2) + "px";
      e.style.backgroundColor = base; e.style.backgroundImage = tex;
      var layers = [];
      for (var s = 0; s < STAGES; s++) {
        var k = document.createElement("div");
        k.className = "bb-k"; k.style.backgroundImage = ck[s];
        e.appendChild(k); layers.push(k);
      }
      var sh = document.createElement("div"); sh.className = "bb-shade"; e.appendChild(sh);
      grid.appendChild(e);

      // 1) place: centre first, every block down by 0.30s
      var tIn = dist * 0.18 + rnd() * 0.02;
      tl.fromTo(e, { scale: 0.2, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.1, ease: "back.out(1.8)" }, tIn);
      // 2) break stages spread outward
      var tCrack = 0.14 + dist * 0.16 + rnd() * 0.03;
      for (var s2 = 0; s2 < STAGES; s2++) {
        tl.set(layers[s2], { opacity: 1 }, tCrack + s2 * 0.05);
        if (s2) tl.set(layers[s2 - 1], { opacity: 0 }, tCrack + s2 * 0.05);
      }
      // 3) shatter: the block swaps for F x F fragments that pop up, spin and fall
      var tBreak = 0.52 + dist * 0.2 + rnd() * 0.02;
      tl.set(e, { opacity: 0 }, tBreak);
      for (var fy = 0; fy < F; fy++) {
        for (var fx = 0; fx < F; fx++) {
          var f = document.createElement("div");
          f.className = "bb-f";
          f.style.left = (x0 + fx * FS) + "px"; f.style.top = (y0 + fy * FS) + "px";
          f.style.width = (FS + 1) + "px"; f.style.height = (FS + 1) + "px";
          f.style.backgroundColor = base;
          f.style.backgroundImage = ck[STAGES - 1] + ", " + tex;
          f.style.backgroundSize = B + "px " + B + "px";
          f.style.backgroundPosition = (-fx * FS) + "px " + (-fy * FS) + "px";
          frags.appendChild(f);
          var dx = (fx - 1) * 0.8 + (x0 + B / 2 - W / 2) / (W / 2) * 0.9 + (rnd() - 0.5) * 0.8;
          var up = 18 + rnd() * 36 + (F - 1 - fy) * 8, fall = 170 + rnd() * 150;
          var dur = 0.34 + rnd() * 0.1;
          tl.set(f, { opacity: 1 }, tBreak);
          tl.fromTo(f, { x: 0, rotation: 0, scale: 1 }, {
            x: dx * (60 + rnd() * 50), rotation: (rnd() - 0.5) * 300, scale: 0.35 + rnd() * 0.25,
            duration: dur, ease: "power1.out"
          }, tBreak);
          tl.fromTo(f, { y: 0 }, { keyframes: [
            { y: -up, duration: dur * 0.3, ease: "power2.out" },
            { y: fall, duration: dur * 0.7, ease: "power2.in" }
          ] }, tBreak);
          tl.to(f, { opacity: 0, duration: dur * 0.35, ease: "power1.in" }, tBreak + dur * 0.65);
        }
      }
    }
  }
  return tl;
});

