#lc-group { position: absolute; }
#lc-icon {
  position: absolute; left: 0; top: 0;
  background: var(--ink); border: 3px solid #000;
  display: flex; align-items: center; justify-content: center;
  box-shadow: inset 0 0 0 5px var(--accent), inset 8px 8px 0 rgba(255,255,255,0.18), inset -8px -8px 0 rgba(0,0,0,0.35), 5px 6px 0 rgba(0,0,0,0.45);
}
#lc-art { position: relative; }
#lc-glyph { position: absolute; color: var(--paper); line-height: 1; }
#lc-wrap { position: absolute; overflow: hidden; padding: 0 10px 10px 0; }
#lc-panel { position: relative; display: block; white-space: nowrap; border-left-width: 0; overflow: hidden; }
#lc-stripe { position: absolute; left: 0; right: 0; top: 0; height: 6px; background: var(--accent); border-bottom: 2px solid #000; }
#lc-name { position: absolute; color: var(--paper); line-height: 1; white-space: nowrap; }
#lc-shine {
  position: absolute; top: -20px; bottom: -20px; width: 26px; left: 0;
  background: rgba(255,255,255,0.22); box-shadow: 18px 0 0 rgba(255,255,255,0.1);
}
#lc-subwrap { position: absolute; overflow: hidden; padding: 0 8px 8px 0; }
#lc-sub {
  display: block; background: var(--paper); color: var(--ink); white-space: pre; line-height: 1;
  border: 3px solid #000; box-shadow: 4px 4px 0 #000;
}
#lc-sub .lc-d { display: inline-block; text-align: center; }

