MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var text = String(v.text || "").trim().toUpperCase();
  var sub = String(v.sub || "").trim().toUpperCase();
  var iconKey = String(v.icon || "").trim();
  var accent = String(v.color || "#B072FF");
  S.root.style.setProperty("--accent", accent);

  /* ---- 10x10 pixel icons ---- */
  var K = "#0b0b0d";
  var ICONS = {
    portal: { rows: ["oooooooooo", "oPpppPpPpo", "opPpPpppPo", "oppPppPppo", "oPpppPpPpo", "opPpPpppPo", "oppPppPppo", "oPpppPpPpo", "opPpppPppo", "oooooooooo"],
              pal: { o: "#2a1f45", p: "#8d3bff", P: "#d4a4ff" } },
    compass: { rows: ["..kkkkkk..", ".kSSSSSSk.", "kSsssrssSk", "kSssrrrsSk", "kSsssrssSk", "kSssswssSk", "kSsswwwsSk", "kSssswssSk", ".kSSSSSSk.", "..kkkkkk.."],
               pal: { k: K, S: "#8a8a8a", s: "#c9c9c9", r: "#FF4B4B", w: "#ffffff" } },
    eye: { rows: ["..........", "...kkkk...", "..kggggk..", ".kgGyyGgk.", ".kGykkyGk.", ".kGykkyGk.", ".kgGyyGgk.", "..kggggk..", "...kkkk...", ".........."],
           pal: { k: K, g: "#2f9e7c", G: "#1d6b55", y: "#c6e36b" } },
    sun: { rows: ["....yy....", ".y..yy..y.", "..yYYYYy..", "..YYYYYY..", "yyYYwYYYyy", "yyYYYYYYyy", "..YYYYYY..", "..yYYYYy..", ".y..yy..y.", "....yy...."],
           pal: { y: "#FFCC33", Y: "#ffe27a", w: "#ffffff" } },
    moon: { rows: ["..kkkkkk..", ".kmmmmmmk.", "kmmMmmmmmk", "kmMMmmmmmk", "kmmmmmMmmk", "kmmmmmMMmk", "kmmMmmmmmk", "kmmmmmmmmk", ".kmmmmmmk.", "..kkkkkk.."],
            pal: { k: K, m: "#e9ecf5", M: "#a9b0c6" } },
    diamond: { rows: ["..........", "..kkkkkk..", ".kwwddddk.", "kwddddddDk", "kddddddDDk", ".kddddDDk.", "..kddDDk..", "...kdDk...", "....kk....", ".........."],
               pal: { k: K, w: "#d9fffb", d: "#4FE0D6", D: "#1e9c93" } },
    emerald: { rows: ["..........", "..kkkkkk..", ".kwwddddk.", "kwddddddDk", "kddddddDDk", ".kddddDDk.", "..kddDDk..", "...kdDk...", "....kk....", ".........."],
               pal: { k: K, w: "#c9ffd9", d: "#3fd46a", D: "#16843a" } },
    gold: { rows: ["..........", "..kkkkkk..", ".kwwddddk.", "kwddddddDk", "kddddddDDk", ".kddddDDk.", "..kddDDk..", "...kdDk...", "....kk....", ".........."],
            pal: { k: K, w: "#fff6c4", d: "#FFCC33", D: "#c08a12" } },
    heart: { rows: ["..........", ".kkk..kkk.", "kwrrkkrrrk", "kwrrrrrrrk", "krrrrrrrRk", ".krrrrrRk.", "..krrrRk..", "...krRk...", "....kk....", ".........."],
             pal: { k: K, w: "#ffc2c2", r: "#FF4B4B", R: "#b52323" } },
    skull: { rows: ["..kkkkkk..", ".kwwwwwwk.", "kwwwwwwwwk", "kwkkwwkkwk", "kwkkwwkkwk", "kwwwkkwwwk", ".kwwwwwwk.", "..kwkwkwk.", "..kkkkkkk.", ".........."],
             pal: { k: K, w: "#ecebe4" } },
    pick: { rows: ["...kkkkk..", "..kdddddk.", "...kkkkddk", "......kddk", ".....kbkdk", "....kbk.k.", "...kbk....", "..kbk.....", ".kbk......", "kbk......."],
            pal: { k: K, d: "#4FE0D6", b: "#9a6a3c" } }
  };

  /* ---- layout ---- */
  var ICON = d.vertical ? 96 : 88;
  var nameMaxW = (d.vertical ? W * 0.9 : W * 0.64) - ICON;
  var nameSize = Math.floor(Math.min(d.vertical ? 46 : 52, nameMaxW / (Math.max(text.length, 1) * 0.56 + 1.3)));
  var panelH = ICON - 10;
  var padL = 22, padR = Math.round(nameSize * 0.7);
  var panelW = Math.round(text.length * nameSize * 0.56 + padL + padR);
  var subSize = sub ? Math.floor(Math.min(d.vertical ? 20 : 18, (W * 0.8) / (sub.length * 0.62))) : 0;

  var groupW = ICON - 8 + panelW + 10;
  var g = document.getElementById("lc-group");
  g.style.left = Math.round((W - groupW) / 2) + "px";
  g.style.top = Math.round(d.vertical ? H * 0.15 : H * 0.11) + "px";

  var icon = document.getElementById("lc-icon");
  icon.style.width = ICON + "px"; icon.style.height = ICON + "px";
  var art = document.getElementById("lc-art"), gl = document.getElementById("lc-glyph");
  var def = ICONS[iconKey.toLowerCase()];
  if (def) {
    art.innerHTML = MC.pixelSVG(def.rows, def.pal, Math.round(ICON * 0.56 / 10));
    gl.style.display = "none";
  } else {
    var glyph = (iconKey || MC.plain(text).replace(/[^A-Z0-9]/g, "").charAt(0) || "!").slice(0, 2).toUpperCase();
    gl.textContent = glyph;
    gl.style.fontSize = Math.round(ICON * (glyph.length > 1 ? 0.4 : 0.58)) + "px";
    art.style.display = "none";
  }

  var wrap = document.getElementById("lc-wrap"), panel = document.getElementById("lc-panel");
  wrap.style.left = (ICON - 8) + "px"; wrap.style.top = "5px";
  panel.style.width = panelW + "px"; panel.style.height = panelH + "px";
  var nm = document.getElementById("lc-name");
  nm.textContent = "";
  nm.style.fontSize = nameSize + "px";
  nm.style.left = padL + "px";
  nm.style.top = Math.round(6 + (panelH - 6 - nameSize) / 2 + nameSize * 0.08) + "px";
  var chars = MC.renderLines(nm, [text], { chars: true }).chars;
  var shine = document.getElementById("lc-shine");

  var sw = document.getElementById("lc-subwrap"), sEl = document.getElementById("lc-sub");
  var digits = [], finals = [];
  if (sub) {
    sEl.textContent = "";
    sEl.style.fontSize = subSize + "px";
    sEl.style.padding = Math.round(subSize * 0.42) + "px " + Math.round(subSize * 0.6) + "px " + Math.round(subSize * 0.3) + "px";
    Array.prototype.forEach.call(sub, function (ch) {
      var sp = document.createElement("span");
      sp.textContent = ch;
      if (/[0-9]/.test(ch)) { sp.className = "lc-d"; sp.style.width = "0.62em"; digits.push(sp); finals.push(ch); }
      sEl.appendChild(sp);
    });
    sw.style.left = (ICON + 6) + "px";
    sw.style.top = (5 + panelH + 2) + "px";
  } else {
    sw.style.display = "none";
  }

  /* ---- timeline ---- */
  var D = d.duration;
  var tl = gsap.timeline({ paused: true });
  tl.fromTo(icon, { y: -70, scale: 0.4, rotation: -90 }, { y: 0, scale: 1, rotation: 0, duration: 0.36, ease: "back.out(2.2)" }, 0);
  tl.fromTo(panel, { xPercent: -101 }, { xPercent: 0, duration: 0.34, ease: "power4.out" }, 0.16);
  tl.fromTo(chars, { y: nameSize * 0.9, opacity: 0 }, {
    y: 0, opacity: 1, duration: 0.22, ease: "back.out(2.4)",
    stagger: { each: Math.min(0.035, 0.45 / Math.max(chars.length, 1)) }
  }, 0.3);
  tl.fromTo(shine, { x: -60, skewX: -20 }, { x: panelW + 40, skewX: -20, duration: 0.42, ease: "power2.inOut" }, 0.95);
  if (sub) {
    tl.fromTo(sEl, { yPercent: -140 }, { yPercent: 0, duration: 0.26, ease: "back.out(2)" }, 0.5);
    var proxy = { p: 0 }, nd = digits.length;
    var scramble = function () {
      var p = proxy.p, step = Math.floor(p * 18);
      for (var i = 0; i < nd; i++) {
        var settle = 0.25 + 0.7 * (i + 1) / (nd + 1);
        digits[i].textContent = p >= settle ? finals[i] : String(Math.floor(MC.rng(7919 + step * 131 + i * 17)() * 10));
      }
    };
    if (nd) {
      scramble();
      tl.fromTo(proxy, { p: 0 }, { p: 1, duration: 0.8, ease: "none", onUpdate: scramble }, 0.52);
    }
  }
  tl.to(icon, { keyframes: [{ y: -10, rotation: -8, duration: 0.12, ease: "power2.out" }, { y: 0, rotation: 0, duration: 0.22, ease: "bounce.out" }] }, 1.45);
  // exit
  var out = D - 0.45;
  if (sub) tl.to(sEl, { yPercent: -140, duration: 0.16, ease: "power2.in" }, out);
  tl.to(chars, { y: -nameSize, opacity: 0, duration: 0.16, ease: "power2.in", stagger: { each: 0.008 } }, out + 0.04);
  tl.to(panel, { xPercent: -101, duration: 0.22, ease: "power3.in" }, out + 0.12);
  tl.to(icon, { scale: 0, rotation: 120, duration: 0.2, ease: "back.in(2)" }, out + 0.24);
  return tl;
});

