.cd-tick { position: absolute; border: 2px solid #000; background: rgba(18,19,21,0.55); }
.cd-tick-on { position: absolute; inset: -2px; border: 2px solid #000; opacity: 0;
  box-shadow: inset 2px 2px 0 rgba(255,255,255,0.4); }
.cd-bit { position: absolute; border: 2px solid #000; }
#cd-go { position: absolute; left: 0; width: 100%; text-align: center; line-height: 1; white-space: nowrap; }

