  /* ---- GO ---- */
  var go = document.getElementById("cd-go");
  var goSize = Math.floor(Math.min(d.vertical ? 150 : 170, (W * 0.86) / (Math.max(goText.length, 1) * 0.56)));
  go.textContent = goText;
  go.style.fontSize = goSize + "px";
  go.style.top = (cy - goSize * 0.5) + "px";
  go.style.color = goColor;
  go.style.transformOrigin = "50% 50%";
  var goLit = litTicks(goColor);
  goLit.forEach(function (on) {
    tl.fromTo(on, { opacity: 0, scale: 2 }, { opacity: 1, scale: 1, duration: 0.08 }, tGo);
  });
  tl.to(tickBox, { scale: 1.45, opacity: 0, duration: Math.min(0.4, GO_LEN * 0.45), ease: "power2.out" }, tGo + 0.06);
  tl.fromTo(go, { scale: 3, opacity: 0, rotation: -10 }, { scale: 1, opacity: 1, rotation: -3, duration: 0.2, ease: "power4.out" }, tGo);
  var shake = document.getElementById("cd-shake");
  tl.to(shake, { keyframes: [{ x: -9, y: 6 }, { x: 8, y: -5 }, { x: -6, y: -4 }, { x: 4, y: 3 }, { x: 0, y: 0 }],
    duration: Math.min(0.26, GO_LEN * 0.3), ease: "none" }, tGo + 0.14);
  // block burst
  var burst = document.getElementById("cd-burst");
  var bcols = [goColor, C.gold, C.paper, MC.shade(goColor, -0.2)];
  for (var q = 0; q < 22; q++) {
    var bit = document.createElement("div");
    var sz = Math.round(P * (0.35 + rnd() * 0.45));
    bit.className = "cd-bit";
    bit.style.width = sz + "px"; bit.style.height = sz + "px";
    bit.style.left = (cx - sz / 2) + "px"; bit.style.top = (cy - sz / 2) + "px";
    bit.style.background = bcols[q % bcols.length];
    burst.appendChild(bit);
    var ang = (q / 22) * Math.PI * 2 + rnd() * 0.25, dist = Math.min(W, H) * (0.32 + rnd() * 0.22);
    var bd = Math.min(0.55, GO_LEN * 0.6);
    tl.fromTo(bit, { x: 0, y: 0, scale: 0.4, rotation: 0, opacity: 1 }, {
      x: Math.cos(ang) * dist * (d.vertical ? 1 : 1.5), y: Math.sin(ang) * dist + P * 1.5,
      scale: 1, rotation: (rnd() - 0.5) * 400, duration: bd, ease: "power3.out"
    }, tGo + 0.1);
    tl.to(bit, { opacity: 0, scale: 0.2, duration: bd * 0.4, ease: "power1.in" }, tGo + 0.1 + bd * 0.6);
  }
  if (GO_LEN > 0.6) tl.to(go, { keyframes: [{ scale: 1.08, rotation: 2, duration: 0.1 }, { scale: 1, rotation: -3, duration: 0.16 }], ease: "power1.inOut" }, tGo + 0.42);
  tl.to(go, { scale: 1.35, opacity: 0, duration: Math.min(0.2, GO_LEN * 0.25), ease: "power2.in" }, D - Math.min(0.22, GO_LEN * 0.27));
  return tl;
});

