{
  "description": "Challenge goal tracker (DIAMONDS 3/10): a GUI panel with a pixel icon, label and count pops in, a segmented bar shows `from` of `total`, then fills to `to` at ~0.9s with a flash, sparkles and an odometer roll on the count. Reaching `total` stamps COMPLETE!. Top-left on landscape (HUD style), top-centre on vertical. Exits over the last 0.4s.",
  "kind": "overlay",
  "duration": 2.5,
  "orientations": ["landscape", "vertical"],
  "vars": {
    "label":  {"type": "string", "label": "Goal label", "default": "DIAMONDS"},
    "from":   {"type": "number", "label": "Count before", "default": 3},
    "to":     {"type": "number", "label": "Count after", "default": 4},
    "total":  {"type": "number", "label": "Goal total (segments; >24 draws 24 proportional segments)", "default": 10},
    "icon":   {"type": "string", "label": "Icon: diamond | emerald | gold | heart | skull | eye | portal | compass | sun | moon | pick, 1-2 characters, or empty", "default": "diamond"},
    "accent": {"type": "color", "label": "Bar colour", "brand": "colors.diamond"},
    "done_text": {"type": "string", "label": "Stamp when to >= total (empty = none)", "default": "COMPLETE!"},
    "opaque": {"type": "boolean", "label": "Opaque ink background", "default": false}
  }
}

