#pt-group { position: absolute; }
#pt-panel { position: absolute; }
#pt-icon {
  position: absolute; background: var(--ink); border: 3px solid #000;
  display: flex; align-items: center; justify-content: center;
  box-shadow: inset 0 0 0 4px var(--accent), inset 6px 6px 0 rgba(255,255,255,0.16), inset -6px -6px 0 rgba(0,0,0,0.35), 4px 5px 0 rgba(0,0,0,0.45);
}
#pt-art { position: relative; }
#pt-glyph { position: absolute; color: var(--paper); line-height: 1; }
