toolu_0192wHUncu24ujXsSx9ZnWQM.content:
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration;
  var label = String(v.label || "").trim().toUpperCase();
  var total = Math.max(1, Math.round(MC.num(v.total, 10)));
  var from = Math.max(0, Math.min(total, Math.round(MC.num(v.from, 3))));
  var to = Math.max(0, Math.min(total, Math.round(MC.num(v.to, from + 1))));
  var iconKey = String(v.icon == null ? "" : v.icon).trim();
  var accent = String(v.accent || "#4FE0D6");
  var doneText = String(v.done_text == null ? "" : v.done_text).trim().toUpperCase();
  S.root.style.setProperty("--accent", accent);
  var GOLD = MC.css("--gold") || "#FFCC33", PAPER = MC.css("--paper") || "#F4F1E8";

  /* ---- 10x10 pixel icons ---- */
  var K = "#0b0b0d";
  var GEM = ["..........", "..kkkkkk..", ".kwwddddk.", "kwddddddDk", "kddddddDDk", ".kddddDDk.", "..kddDDk..", "...kdDk...", "....kk....", ".........."];
  var ICONS = {
    diamond: { rows: GEM, pal: { k: K, w: "#d9fffb", d: "#4FE0D6", D: "#1e9c93" } },
    emerald: { rows: GEM, pal: { k: K, w: "#c9ffd9", d: "#3fd46a", D: "#16843a" } },
    gold:    { rows: GEM, pal: { k: K, w: "#fff6c4", d: "#FFCC33", D: "#c08a12" } },
    heart: { rows: ["..........", ".kkk..kkk.", "kwrrkkrrrk", "kwrrrrrrrk", "krrrrrrrRk", ".krrrrrRk.", "..krrrRk..", "...krRk...", "....kk....", ".........."],
             pal: { k: K, w: "#ffc2c2", r: "#FF4B4B", R: "#b52323" } },
    skull: { rows: ["..kkkkkk..", ".kwwwwwwk.", "kwwwwwwwwk", "kwkkwwkkwk", "kwkkwwkkwk", "kwwwkkwwwk", ".kwwwwwwk.", "..kwkwkwk.", "..kkkkkkk.", ".........."],
             pal: { k: K, w: "#ecebe4" } },
    eye: { rows: ["..........", "...kkkk...", "..kggggk..", ".kgGyyGgk.", ".kGykkyGk.", ".kGykkyGk.", ".kgGyyGgk.", "..kggggk..", "...kkkk...", ".........."],
           pal: { k: K, g: "#2f9e7c", G: "#1d6b55", y: "#c6e36b" } },
    portal: { rows: ["oooooooooo", "oPpppPpPpo", "opPpPpppPo", "oppPppPppo", "oPpppPpPpo", "opPpPpppPo", "oppPppPppo", "oPpppPpPpo", "opPpppPppo", "oooooooooo"],
              pal: { o: "#2a1f45", p: "#8d3bff", P: "#d4a4ff" } },
    compass: { rows: ["..kkkkkk..", ".kSSSSSSk.", "kSsssrssSk", "kSssrrrsSk", "kSsssrssSk", "kSssswssSk", "kSsswwwsSk", "kSssswssSk", ".kSSSSSSk.", "..kkkkkk.."],
               pal: { k: K, S: "#8a8a8a", s: "#c9c9c9", r: "#FF4B4B", w: "#ffffff" } },
    sun: { rows: ["....yy....", ".y..yy..y.", "..yYYYYy..", "..YYYYYY..", "yyYYwYYYyy", "yyYYYYYYyy", "..YYYYYY..", "..yYYYYy..", ".y..yy..y.", "....yy...."],
           pal: { y: "#FFCC33", Y: "#ffe27a", w: "#ffffff" } },
    moon: { rows: ["..kkkkkk..", ".kmmmmmmk.", "kmmMmmmmmk", "kmMMmmmmmk", "kmmmmmMmmk", "kmmmmmMMmk", "kmmMmmmmmk", "kmmmmmmmmk", ".kmmmmmmk.", "..kkkkkk.."],
            pal: { k: K, m: "#e9ecf5", M: "#a9b0c6" } },
    pick: { rows: ["...kkkkk..", "..kdddddk.", "...kkkkddk", "......kddk", ".....kbkdk", "....kbk.k.", "...kbk....", "..kbk.....", ".kbk......", "kbk......."],
            pal: { k: K, d: "#4FE0D6", b: "#9a6a3c" } }
  };

  /* ---- layout ---- */
  var hasIcon = iconKey !== "";
  var LS0 = d.vertical ? 28 : 26;
  var PH = 12 + LS0 + 10 + 22 + 12;                 // label row + bar
  var ICON = hasIcon ? PH + 10 : 0;
  var PW = d.vertical ? Math.round(W * 0.86) - ICON / 2 : 380;
  var padL = hasIcon ? Math.round(ICON / 2 + 14) : 16, padR = 16;
  var innerW = PW - padL - padR;

  var g = document.getElementById("pt-group");
  var groupW = ICON / 2 + PW;
  g.style.left = (d.vertical ? Math.round((W - groupW) / 2) : 28) + "px";
  g.style.top = (d.vertical ? Math.round(H * 0.12) : 26) + "px";

  var panel = document.getElementById("pt-panel");
  panel.style.left = (ICON / 2) + "px"; panel.style.top = (hasIcon ? 5 : 0) + "px";
  panel.style.width = PW + "px"; panel.style.height = PH + "px";
  panel.style.transformOrigin = "0% 50%";

  var icon = document.getElementById("pt-icon");
  if (hasIcon) {
    icon.style.left = "0px"; icon.style.top = "0px";
    icon.style.width = ICON + "px"; icon.style.height = ICON + "px";
    var art = document.getElementById("pt-art"), gl = document.getElementById("pt-glyph");
    var def = ICONS[iconKey.toLowerCase()];
    if (def) { art.innerHTML = MC.pixelSVG(def.rows, def.pal, Math.round(ICON * 0.6 / 10)); gl.style.display = "none"; }
    else {
      var glyph = iconKey.slice(0, 2).toUpperCase();
      gl.textContent = glyph; gl.style.fontSize = Math.round(ICON * (glyph.length > 1 ? 0.4 : 0.58)) + "px";
      art.style.display = "none";
    }
  } else {
    icon.style.display = "none";
  }

  // count "3/10": numerator rolls old -> new
  var digits = Math.max(String(from).length, String(to).length);
  var totStr = "/" + total;
  var CS = Math.round(LS0 * 1.12);
  var countW = (digits + totStr.length) * CS * 0.58;
  var cEl = document.getElementById("pt-count");
  cEl.style.fontSize = CS + "px";
  cEl.style.right = padR + "px"; cEl.style.top = (12 + LS0 - CS) + "px";
  cEl.style.transformOrigin = "100% 60%";
  var nw = document.getElementById("pt-numwrap"), oEl = document.getElementById("pt-old"), nEl = document.getElementById("pt-new");
  nw.style.width = Math.ceil(digits * CS * 0.6) + "px"; nw.style.height = Math.ceil(CS * 1.08) + "px";
  oEl.textContent = String(from); nEl.textContent = String(to);
  document.getElementById("pt-total").textContent = totStr;
  if (from === to) nEl.style.display = "none";

  var LS = Math.floor(Math.min(LS0, (innerW - countW - 14) / (Math.max(label.length, 1) * 0.56)));
  var lEl = document.getElementById("pt-label");
  lEl.textContent = label; lEl.style.fontSize = LS + "px";
  lEl.style.left = padL + "px"; lEl.style.top = (12 + (LS0 - LS) + LS * 0.06) + "px";

  // segments
  var N = Math.min(total, 24);
  function seg(x) { return total <= 24 ? x : Math.round(x / total * 24); }
  var s0 = seg(from), s1 = seg(to);
  var bar = document.getElementById("pt-bar");
  var BH = 22, GAP = N > 16 ? 2 : 3, barTop = 12 + LS0 + 10;
  bar.style.left = padL + "px"; bar.style.top = barTop + "px";
  bar.style.width = innerW + "px"; bar.style.height = BH + "px";
  var segW = (innerW - GAP * (N - 1)) / N;
  var segs = [], fills = [], flashes = [];
  for (var i = 0; i < N; i++) {
    var sg = document.createElement("div");
    sg.className = "pt-seg";
    sg.style.left = (i * (segW + GAP)) + "px"; sg.style.top = "0px";
    sg.style.width = segW + "px"; sg.style.height = BH + "px";
    var f = document.createElement("div"); f.className = "pt-fill"; f.style.transformOrigin = "0% 50%";
    var fl = document.createElement("div"); fl.className = "pt-flash";
    sg.appendChild(f); sg.appendChild(fl); bar.appendChild(sg);
    segs.push(sg); fills.push(f); flashes.push(fl);
  }

  /* ---- timeline ---- */
  var rnd = MC.rng(808);
  var tl = gsap.timeline({ paused: true });
  if (hasIcon) tl.fromTo(icon, { scale: 0, rotation: -160 }, { scale: 1, rotation: 0, duration: 0.34, ease: "back.out(2.2)" }, 0);
  tl.fromTo(panel, { scaleX: 0.2, opacity: 0 }, { scaleX: 1, opacity: 1, duration: 0.3, ease: "back.out(1.6)" }, 0.08);
  tl.fromTo(lEl, { x: -14, opacity: 0 }, { x: 0, opacity: 1, duration: 0.2, ease: "power2.out" }, 0.24);
  tl.fromTo(cEl, { scale: 0.4, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.22, ease: "back.out(2.4)" }, 0.3);
  tl.fromTo(segs, { scaleY: 0 }, { scaleY: 1, duration: 0.14, ease: "back.out(2.5)", stagger: Math.min(0.025, 0.3 / N) }, 0.28);
  // already-earned segments are filled from the start; the change animates at T_FILL
  var T_FILL = 0.9;
  var lo = Math.min(s0, s1), hi = Math.max(s0, s1), gain = s1 >= s0;
  var each = Math.min(0.1, 0.7 / Math.max(hi - lo, 1));
  fills.forEach(function (fEl, j) {
    if (j < lo) return;                                  // stays full
    if (j >= hi) { tl.set(fEl, { scaleX: 0 }, 0); return; }
    var t = T_FILL + (gain ? (j - lo) : (hi - 1 - j)) * each;
    if (gain) tl.fromTo(fEl, { scaleX: 0 }, { scaleX: 1, duration: 0.16, ease: "power3.out" }, t);
    else tl.fromTo(fEl, { scaleX: 1 }, { scaleX: 0, duration: 0.16, ease: "power3.in" }, t);
    tl.fromTo(flashes[j], { opacity: 0.95 }, { opacity: 0, duration: 0.3, ease: "power2.out" }, t + 0.05);
    tl.fromTo(segs[j], { y: 0 }, { keyframes: [{ y: -5, duration: 0.07 }, { y: 0, duration: 0.14, ease: "bounce.out" }] }, t);
    // sparks
    var sp = document.getElementById("pt-sparks");
    var cxs = padL + j * (segW + GAP) + segW / 2, cys = barTop + BH / 2;
    for (var q = 0; q < 6; q++) {
      var s = document.createElement("div");
      var sz = 4 + Math.floor(rnd() * 5);
      s.className = "pt-spark";
      s.style.width = sz + "px"; s.style.height = sz + "px";
      s.style.left = (cxs - sz / 2) + "px"; s.style.top = (cys - sz / 2) + "px";
      s.style.background = gain ? [accent, PAPER, GOLD][q % 3] : ["#FF4B4B", PAPER][q % 2];
      sp.appendChild(s);
      var a = -Math.PI / 2 + (rnd() - 0.5) * 2.4, dist = 22 + rnd() * 30;
      tl.set(s, { opacity: 1 }, t + 0.04);
      tl.fromTo(s, { x: 0, y: 0, rotation: 0 }, { x: Math.cos(a) * dist, y: Math.sin(a) * dist, rotation: (rnd() - 0.5) * 300, duration: 0.4, ease: "power2.out" }, t + 0.04);
      tl.to(s, { opacity: 0, duration: 0.16 }, t + 0.3);
    }
  });
  if (from !== to) {
    var tc = T_FILL + 0.04;
    tl.fromTo(oEl, { yPercent: 0 }, { yPercent: -110, duration: 0.2, ease: "power2.in" }, tc);
    tl.fromTo(nEl, { yPercent: 110 }, { yPercent: 0, duration: 0.24, ease: "back.out(2.2)" }, tc + 0.1);
    tl.fromTo(cEl, { scale: 1 }, { keyframes: [{ scale: 1.32, duration: 0.1, ease: "power2.out" }, { scale: 1, duration: 0.24, ease: "back.out(2)" }] }, tc + 0.1);
    tl.fromTo(nw, { color: "#ffffff" }, { color: gain ? accent : "#FF4B4B", duration: 0.5, ease: "power1.in" }, tc + 0.1);
    if (hasIcon) tl.fromTo(icon, { y: 0, rotation: 0 }, { keyframes: [{ y: -12, rotation: 10, duration: 0.12, ease: "power2.out" }, { y: 0, rotation: 0, duration: 0.26, ease: "bounce.out" }] }, tc + 0.06);
  }
  var done = document.getElementById("pt-done");
  if (to >= total && doneText && from !== to) {
    var dS = Math.round(LS0 * 0.78);
    done.textContent = doneText; done.style.fontSize = dS + "px";
    done.style.padding = Math.round(dS * 0.32) + "px " + Math.round(dS * 0.5) + "px " + Math.round(dS * 0.16) + "px";
    done.style.right = "0px"; done.style.top = (panel.offsetTop + PH - 6) + "px";
    done.style.left = "auto";
    var td = T_FILL + (hi - lo) * each + 0.22;
    tl.fromTo(done, { scale: 2.6, opacity: 0, rotation: 14 }, { scale: 1, opacity: 1, rotation: -4, duration: 0.2, ease: "power4.out" }, td);
    tl.fromTo(flashes, { opacity: 0.85 }, { opacity: 0, duration: 0.35, immediateRender: false }, td + 0.04);
  } else {
    done.style.display = "none";
  }
  // exit
  tl.to(g, { y: -(ICON + PH + 80), duration: 0.32, ease: "back.in(1.6)" }, D - 0.38);
  return tl;
});

