#qc-title {
  position: absolute; background: var(--accent); color: var(--ink); text-align: center;
  border: 3px solid #000; line-height: 1; white-space: nowrap;
  box-shadow: inset -4px -4px 0 rgba(0,0,0,0.25), inset 4px 4px 0 rgba(255,255,255,0.4), 5px 6px 0 #000;
}
#qc-title .mc-line { display: block; }
.qc-card { position: absolute; }
.qc-inner {
  position: absolute; inset: 0;
  background: var(--cc); border: 4px solid #000;
  box-shadow: inset 6px 6px 0 rgba(255,255,255,0.28), inset -6px -6px 0 rgba(0,0,0,0.3), 6px 7px 0 rgba(0,0,0,0.5);
  display: flex; align-items: center; justify-content: center;
}
.qc-inner::before { /* pixel speckle texture */
  content: ""; position: absolute; inset: 10px;
  background-image:
    linear-gradient(rgba(0,0,0,0.07) 50%, transparent 50%),
    linear-gradient(90deg, rgba(255,255,255,0.05) 50%, transparent 50%);
  background-size: 24px 24px, 36px 36px;
}
.qc-text { position: relative; color: var(--paper); text-align: center; line-height: 1.08; }
.qc-tag {
  position: absolute; background: var(--ink); color: var(--cc); border: 3px solid #000;
  display: flex; align-items: center; justify-content: center; line-height: 1;
  box-shadow: inset 3px 3px 0 rgba(255,255,255,0.18), 3px 4px 0 #000;
}
#qc-or {
  position: absolute; background: var(--ink); color: var(--paper); border: 3px solid #000;
  display: flex; align-items: center; justify-content: center; line-height: 1;
  box-shadow: inset 0 0 0 4px var(--accent), inset 6px 6px 0 rgba(255,255,255,0.15), 4px 5px 0 #000;
}

