input.content:
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration;
  var title = String(v.title || "").trim().toUpperCase();
  var A = String(v.a || "").trim().toUpperCase(), B = String(v.b || "").trim().toUpperCase();
  var orText = String(v.or_text == null ? "OR" : v.or_text).trim().toUpperCase();
  S.root.style.setProperty("--accent", String(v.accent || "#FFCC33"));
  var K = 0.56;

  /* ---- title plate ---- */
  var tEl = document.getElementById("qc-title");
  var tFit = MC.fit(title || " ", d.vertical
    ? { maxWidth: W * 0.8, maxSize: 46, minSize: 18, k: K, maxLines: 2, maxHeight: H * 0.1 }
    : { maxWidth: W * 0.66, maxSize: 46, minSize: 18, k: K, maxLines: 2, maxHeight: H * 0.16 });
  tEl.style.fontSize = tFit.size + "px";
  MC.renderLines(tEl, tFit.lines);
  var tLen = Math.max.apply(null, tFit.lines.map(function (l) { return l.length; }));
  var tW = Math.round(tLen * tFit.size * K + tFit.size * 1.3);
  var tH = Math.round(tFit.lines.length * tFit.size * 1.05 + tFit.size * 0.62);
  tEl.style.width = tW + "px";
  tEl.style.padding = Math.round(tFit.size * 0.38) + "px 0 0";
  tEl.style.height = tH + "px";
  tEl.style.left = Math.round((W - tW) / 2) + "px";
  var tTop = Math.round(d.vertical ? H * 0.13 : H * 0.08);
  tEl.style.top = tTop + "px";
  if (!title) tEl.style.display = "none";

  /* ---- option cards ---- */
  var cw, ch, ax, ay, bx, by, orX, orY;
  if (d.vertical) {
    cw = Math.round(W * 0.84); ch = Math.round(H * 0.17);
    ax = bx = Math.round((W - cw) / 2);
    ay = Math.round(tTop + tH + 44); by = ay + ch + 58;
    orX = W / 2; orY = ay + ch + 29;
  } else {
    cw = Math.round(W * 0.37); ch = Math.round(H * 0.42);
    ax = Math.round(W / 2 - cw - 36); bx = Math.round(W / 2 + 36);
    ay = by = Math.round(Math.max(tTop + tH + 44, H * 0.34));
    orX = W / 2; orY = ay + ch / 2;
  }
  function card(id, txt, color, x, y) {
    var el = document.getElementById(id);
    el.style.setProperty("--cc", color);
    el.style.left = x + "px"; el.style.top = y + "px";
    el.style.width = cw + "px"; el.style.height = ch + "px";
    var te = el.querySelector(".qc-text");
    var f = MC.fit(txt || " ", { maxWidth: cw * 0.8, maxSize: d.vertical ? 42 : 40, minSize: 14, k: K, maxLines: 3, maxHeight: ch * 0.62, lineHeight: 1.1 });
    te.style.fontSize = f.size + "px";
    te.style.top = Math.round(f.size * 0.08) + "px";
    var parts = MC.renderLines(te, f.lines);
    var tag = el.querySelector(".qc-tag"), TS = d.vertical ? 46 : 48;
    tag.style.width = TS + "px"; tag.style.height = TS + "px";
    tag.style.left = "-16px"; tag.style.top = "-16px";
    tag.style.fontSize = Math.round(TS * 0.62) + "px";
    tag.style.paddingTop = Math.round(TS * 0.08) + "px";
    return { el: el, inner: el.querySelector(".qc-inner"), words: parts.words, tag: tag };
  }
  var ca = card("qc-a", A, String(v.a_color || "#FF4B4B"), ax, ay);
  var cb = card("qc-b", B, String(v.b_color || "#4FE0D6"), bx, by);

